exports.slug = (value) => {
  if (typeof value !== 'string' || !value.trim() || !/^[A-Za-z0-9_\s-]+$/.test(value)) throw new TypeError('Invalid identifier');
  return value.trim().toLowerCase().replace(/[\s-]+/g, '_');
};

const test = require('node:test');
const assert = require('node:assert/strict');
const { documentKey } = require('../src/caller.cjs');
test('customized identifier uses underscores and preserves zero', () => {
  assert.equal(documentKey('007 Launch - Notes'), 'notes/007_launch_notes.md');
});
